<div><div class="card"><div class="card-header d-flex gap-2"><input class="form-control" placeholder="Model / ID" wire:model.live.debounce.300ms="search"><select class="form-select" wire:model.live="event"><option value="">All events</option><option>created</option><option>updated</option><option>deleted</option><option>restored</option></select></div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Time</th><th>User</th><th>Event</th><th>Record</th><th>Before</th><th>After</th><th>IP</th></tr></thead><tbody>@foreach($logs as $log)<tr><td>{{$log->created_at}}</td><td>{{$log->user?->name?:'System'}}</td><td>{{$log->event}}</td><td>{{class_basename($log->auditable_type)}} #{{$log->auditable_id}}</td><td><code>{{json_encode($log->before,JSON_UNESCAPED_UNICODE)}}</code></td><td><code>{{json_encode($log->after,JSON_UNESCAPED_UNICODE)}}</code></td><td>{{$log->ip_address}}</td></tr>@endforeach</tbody></table></div><div class="card-footer">{{$logs->links()}}</div></div></div>
